-- Public site copy and the massage-type catalog.
-- This is site content, not CRM demo data: `install` runs it so the marketing
-- pages are never empty, while customer/session/expense tables stay untouched.
-- INSERT IGNORE everywhere so re-running never overwrites the owner's edits.
SET NAMES utf8mb4;

INSERT IGNORE INTO site_blocks (`key`, `value`, `group_name`, `type`) VALUES
('site.brand', '', 'site', 'text'),
('home.hero.title', 'بدنی آرام، ذهنی رهاشده', 'home', 'text'),
('home.hero.lead', 'ماساژ تخصصی آقایان و بانوان، در دو مرکز مستقل با درمانگران مجرب. نوبت خود را آنلاین انتخاب کنید یا با ما تماس بگیرید.', 'home', 'textarea'),
('home.hero.primary', 'رزرو نوبت آنلاین', 'home', 'text'),
('home.hero.secondary', 'دیدن انواع ماساژ', 'home', 'text'),
('home.intro.title', 'چرا اینجا', 'home', 'text'),
('home.intro.body', 'اتاق‌های جداگانه برای آقایان و بانوان، روغن و حوله تازه برای هر مهمان، و درمانگری که پیش از شروع درباره نیاز بدن شما می‌پرسد. اگر محدودیت جسمی یا حساسیت پوستی دارید، همان اول بگویید تا جلسه بر اساس آن تنظیم شود.', 'home', 'textarea'),
('services.title', 'انواع ماساژ', 'services', 'text'),
('services.lead', 'هر جلسه با پرسش کوتاه درباره نیاز بدن شما شروع می‌شود. اگر بین دو گزینه مردد هستید، هنگام رزرو توضیح دهید تا راهنمایی شوید.', 'services', 'textarea'),
('centers.title', 'دو مرکز، دو فضای مستقل', 'centers', 'text'),
('centers.men.title', 'مرکز ماساژ آقایان', 'centers', 'text'),
('centers.men.body', 'فضای اختصاصی آقایان با درمانگران مرد. ورود، رختکن و اتاق‌های ماساژ کاملاً جدا از بخش بانوان است.', 'centers', 'textarea'),
('centers.women.title', 'مرکز ماساژ بانوان', 'centers', 'text'),
('centers.women.body', 'فضای اختصاصی بانوان با درمانگران زن. ورود، رختکن و اتاق‌های ماساژ کاملاً جدا از بخش آقایان است.', 'centers', 'textarea'),
('booking.title', 'رزرو نوبت آنلاین', 'booking', 'text'),
('booking.lead', 'زمان‌های خالی هر مرکز را ببینید و نوبت خود را ثبت کنید. نوبت پس از تأیید مرکز قطعی می‌شود و وضعیت آن را با کد پیگیری می‌بینید.', 'booking', 'textarea'),
('gift.title', 'کارت هدیه ماساژ', 'gift', 'text'),
('gift.lead', 'کارت هدیه را برای کسی بخرید که به یک ساعت آرامش نیاز دارد. پس از پرداخت، کد اختصاصی برای شما و گیرنده صادر می‌شود.', 'gift', 'textarea'),
('contact.title', 'تماس و آدرس', 'contact', 'text'),
('contact.body', 'برای تغییر یا لغو نوبت، حداقل چند ساعت قبل خبر دهید تا زمان به مهمان دیگری برسد.', 'contact', 'textarea'),
('contact.phone', '', 'contact', 'text'),
('contact.address', '', 'contact', 'text'),
('contact.hours', '', 'contact', 'text'),
('social.instagram', '', 'social', 'url'),
('social.telegram', '', 'social', 'url'),
('social.whatsapp', '', 'social', 'url'),
('footer.note', '', 'footer', 'text'),
('education.title', 'بخش آموزش', 'education', 'text'),
('education.body', 'دوره‌های کوتاه آشنایی با تکنیک‌های ماساژ برای علاقه‌مندان و کارکنان مراکز. برای اطلاع از زمان دوره‌ها و شرایط ثبت‌نام تماس بگیرید.', 'education', 'textarea');

INSERT IGNORE INTO massage_types (slug, title, summary, body, illustration, duration_minutes, price_from, sort_order, status) VALUES
('relax', 'ماساژ ریلکسی', 'آرام‌سازی کامل بدن با حرکات آهسته و پیوسته',
 'ماساژ ریلکسی روی بافت‌های سطحی و با ضرب‌آهنگ آرام انجام می‌شود؛ هدفش شل‌کردن تنش روزمره و پایین‌آوردن سطح اضطراب است، نه کار روی گرفتگی عمیق. برای کسانی مناسب است که خسته‌اند، بدخوابی دارند یا اولین تجربه ماساژشان است.', 'relax', 60, NULL, 10, 'active'),
('therapeutic', 'ماساژ درمانی', 'کار موضعی روی گرفتگی و دردهای تکرارشونده',
 'در ماساژ درمانی درمانگر نقطه درد و منشأ آن را پیدا می‌کند و با فشار عمقی‌تر روی همان ناحیه کار می‌کند. برای گردن‌درد و کمردرد ناشی از نشستن طولانی، تنش شانه و گرفتگی عضلات پرکاربرد است. اگر درد تازه و شدید یا آسیب ورزشی دارید، پیش از جلسه اطلاع دهید.', 'therapeutic', 60, NULL, 20, 'active'),
('hot-stone', 'ماساژ سنگ داغ', 'گرمای سنگ بازالت روی نقاط کلیدی بدن',
 'سنگ‌های بازالتی گرم‌شده روی ستون فقرات، شانه و کف پا قرار می‌گیرند و گرمایشان گردش خون را بالا می‌برد و بافت سفت را نرم می‌کند. معمولاً با روغن و حرکات آرام همراه است. برای بدن‌های سرد و گرفتگی‌های مزمن انتخاب خوبی است.', 'hot-stone', 75, NULL, 30, 'active'),
('swedish', 'ماساژ سوئدی', 'روش کلاسیک اروپایی برای گردش خون و رفع خستگی',
 'ماساژ سوئدی از پنج حرکت پایه ساخته می‌شود: لغزش، ورز دادن، ضربه، فشردن و لرزش. ترکیب این حرکات گردش خون و لنف را بهبود می‌دهد و خستگی عضلانی را برمی‌دارد. انتخاب متداول برای ماساژ کامل بدن است.', 'swedish', 60, NULL, 40, 'active'),
('thai', 'ماساژ تایلندی', 'کشش و فشار روی خطوط انرژی، بدون روغن',
 'در ماساژ تایلندی مهمان با لباس راحت روی تشک دراز می‌کشد و درمانگر با دست، ساعد و پا فشار و کشش وارد می‌کند. تمرکز آن روی انعطاف، دامنه حرکتی و رهاسازی تنش عمقی است. برای کسانی که ماساژ روغنی را دوست ندارند گزینه مناسبی است.', 'thai', 90, NULL, 50, 'active'),
('head-face', 'ماساژ سر و صورت', 'برای سردرد تنشی و خستگی چشم',
 'این جلسه روی شانه، گردن، پوست سر و عضلات صورت کار می‌کند و معمولاً بدون درآوردن لباس انجام می‌شود. برای کسانی که ساعت‌ها پشت میز یا مانیتور هستند و سردرد تنشی دارند مناسب است. فشارها ملایم و کوتاه است.', 'head-face', 30, NULL, 60, 'active'),
('thai-yoga', 'ماساژ تای یوگا', 'کشش یوگاگونه با کمک درمانگر',
 'تای یوگا ترکیبی از فشار ریتمیک و کشش‌های یوگاگونه است؛ درمانگر بدن شما را در وضعیت‌های کششی نگه می‌دارد و کنترل حرکت را در دست می‌گیرد. هدف افزایش انعطاف و آزادکردن مفاصل است، نه آرامش کامل. اگر محدودیت مفصلی یا دیسک دارید، حتماً قبل از جلسه بگویید.', 'thai-yoga', 90, NULL, 70, 'active'),
('yumeiho', 'ماساژ یومی هو', 'روش ژاپنی اصلاح لگن و راستای ستون فقرات',
 'یومی هو با فشار کف دست، حرکات کششی و چرخش کنترل‌شده مفاصل، تعادل لگن و ستون فقرات را هدف می‌گیرد و روی لباس انجام می‌شود. برای کسانی که از کمردرد مزمن، کج‌نشینی یا تفاوت فشار دو طرف بدن شکایت دارند کاربرد دارد. در بارداری یا پس از شکستگی تازه انجام نمی‌شود.', 'yumeiho', 60, NULL, 80, 'active'),
('reflexology', 'رفلکسولوژی', 'فشار روی نقاط بازتابی کف پا',
 'رفلکسولوژی با فشار انگشت روی نقاط مشخص کف پا و مچ کار می‌کند؛ هر ناحیه به بخشی از بدن نسبت داده می‌شود. جلسه معمولاً آرام و بدون روغن است و برای کاهش خستگی و بهبود خواب انتخاب می‌شود. حس فشار در برخی نقاط ممکن است بیشتر باشد.', 'reflexology', 45, NULL, 90, 'active'),
('foot', 'فوت ماساژ', 'ماساژ پا و ساق برای خستگی و ورم',
 'ماساژ پا از مچ تا زانو انجام می‌شود و روی خستگی، سنگینی پا و ورم پایان روز کار می‌کند. برای کسانی که زیاد سرپا هستند یا کفش تنگ می‌پوشند مناسب است. اگر واریس یا زخم پوستی دارید، پیش از جلسه اطلاع دهید.', 'foot', 30, NULL, 100, 'active'),
('hot-towel', 'ماساژ حوله داغ', 'کمپرس گرم پیش از کار عمقی',
 'در این جلسه حوله گرم روی عضلات گذاشته می‌شود تا بافت نرم شود و سپس ماساژ انجام می‌گیرد. گرمای مرطوب بیشتر از گرمای خشک به عمق بافت نفوذ می‌کند. برای شانه و کمر سفت گزینه خوبی است.', 'hot-towel', 60, NULL, 110, 'active'),
('slimming', 'ماساژ لاغری', 'کار دستی روی نواحی تجمع چربی و احتباس آب',
 'ماساژ لاغری با حرکات تخلیه لنفاوی و ورز دادن روی پهلو، شکم و ران انجام می‌شود و به کاهش احتباس آب کمک می‌کند. این جلسه جایگزین رژیم و فعالیت بدنی نیست و نتیجه آن موقتی است. برای نتیجه پایدار، برنامه چندجلسه‌ای لازم است.', 'slimming', 45, NULL, 120, 'active'),
('facial', 'فیشال و پاکسازی پوست', 'پاکسازی، لایه‌برداری و ماساژ صورت',
 'فیشال با پاکسازی پوست، لایه‌برداری ملایم و ماساژ صورت انجام می‌شود و با آبرسانی و ماسک پایان می‌یابد. برای پوست کدر، منافذ بسته و پوست خشک مناسب است. اگر پوست حساس، اگزما یا جوش فعال دارید، نوع محصولات را قبل از شروع هماهنگ کنید.', 'facial', 60, NULL, 130, 'active'),
('foot-detox', 'پاکسازی پا و سم‌زدایی', 'خیساندن، اسکراب و ماساژ پا',
 'جلسه با خیساندن پا در آب گرم و نمک انجام می‌شود، سپس اسکراب و ماساژ پا و در پایان کرم مرطوب‌کننده. برای پوست خشک و ترک‌خورده پا و رفع بوی پا کاربرد دارد. در صورت زخم باز یا قارچ فعال پوستی انجام نمی‌شود.', 'foot-detox', 45, NULL, 140, 'active'),
('spiritual', 'پاکسازی روح', 'آرام‌سازی ذهن با رایحه و تنفس',
 'این جلسه ترکیبی از ماساژ آرام، رایحه‌درمانی و چند دقیقه تنفس آگاهانه است؛ هدفش کاهش اضطراب و برگشتن به ریتم آرام بدن است. هیچ ادعای درمانی پزشکی ندارد و جایگزین درمان اختلالات روانی نیست. برای کسانی که بعد از یک دوره پرتنش به توقف نیاز دارند مناسب است.', 'spiritual', 60, NULL, 150, 'active');
